architecture.h4_f:
boodskap = CBOR{v:1, teks, antwoord_na, gestuur_by}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, teks, antwoord_na?, draad_id?, noem?, gestuur_by}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
draad = CBOR{
  v: 1,
  syferteks: hex(ct), // veranderlike lengte
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  gestuur_by: unix_ms
}

cryptoWire.h5_f:
buitenste = CBOR{
  bronnode: hex32,
  teikengebruiker: int64,
  inner_ciphertext: grepe,
  inner_nonce: grepe,
  gestuur_by: unix_ms
}
sig = Ed25519-Sign(source_priv, buitenste)
POST /federation/deliver { koevert: buitenste, sig: hex64 }

