  random = ons ewekansige,
  bedienernaam = ons gasheernaam (of ECH-toegedraai),
  session_id = ons sessie-ID,
}
JA4 = t13d_xxxx_xxxx_xxxx (pas by huidige Chrome-stal)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {naam: x.vortexx.sol}
